"""Independent G4V normal mixer facts from the primary owner chart."""
from curated import add, profile

G4V_MIXER_REFERENCES={'Gemini G4V': {'url': 'https://forum.djtechtools.com/t/midi-out-issues-with-traktor-2/74377', 'sha256': '7a2349f6d0f42e4e9d98055523c605c657d735c309633bfad8a39ae84c7b93f4', 'files': [{'cachePath': 'TestBuilds/r467/upstream/g4v-map.jpg', 'sha256': '7a2349f6d0f42e4e9d98055523c605c657d735c309633bfad8a39ae84c7b93f4'}, {'cachePath': 'TestBuilds/r467/upstream/g4v-table.jpg', 'sha256': 'e429dcfb6773c5b617fc700462794dba31cff1cb0891da8f76fbb33c9812d4b0'}, {'cachePath': 'TestBuilds/r467/upstream/g4v-deck-b.tsi', 'sha256': 'df77724f9a3d44fc1c661e1b9cbdc3817e39efd0b1fbdc57bf3427bb8ccdb802'}, {'cachePath': 'TestBuilds/r468/upstream/g4v.midi.xml', 'sha256': '4b2d33cf8b92c33cca878c715ee185e1cfe69c0b8aea98494ff40d74fbae6480'}, {'cachePath': 'TestBuilds/r468/upstream/g4v-scripts.js', 'sha256': 'eb8cec0fdb970637bfe6bc6c8cd286f3680754a0fa26b89208e3804239de6b14'}, {'cachePath': 'TestBuilds/r468/upstream/g4v-pr4323.json', 'sha256': '09892b938d3eefcc6eb83628d917ce738ed41cf099e9c9469100acdc0e7cdf5e'}], 'relatedSources': [{'url': 'https://us1.discourse-cdn.com/flex001/uploads/techtools/original/3X/8/6/86ec19eecad2c41fb0a06963fad8720622efb248.jpeg'}, {'url': 'https://us1.discourse-cdn.com/flex001/uploads/techtools/original/3X/b/9/b9a64a01048f6aca76092aade627b66d55a5d564.jpeg'}, {'url': 'https://www.geminisound.com/blogs/kb/g2v-g4v-traktor-setup-guide-legacy-kb'}, {'url': 'https://github.com/mixxxdj/mixxx/pull/4323', 'upstreamRevision': 'c7826ca66632be6c88b5138cf2d07ab42726f7fb', 'merged': False}], 'review': 'Primary owner khan.cross published the G4V MIDI chart on29June2016 in the DJ TechTools controller-mapping discussion. The image identifies its creation on18April2016 with Traktor2.10.013. Visually reviewed all four physical strips in order3/1/2/4. Their fixed MIDI channel4/raw3 absolute knobs/faders are CH1..4 gainCC1..4, mid5..8, high9..12, low13..16, filter17..20 and level21..24. Logical CH1..4 map to native A..D, with C/D opt-in and per-source pickup. The separately attached manufacturer-branded G2V/G4V Traktor layout establishes the normal one-to-one mixer functions. These are owner-reported protocol facts, not a manufacturer numeric specification or native hardware test.  R468 independently reviews primary author Javier Vilarroig PR4323 head c7826ca66632be6c88b5138cf2d07ab42726f7fb. The PR is open/unmerged, not a released Mixxx claim. Its XML and component roles qualify manual normal Play1/held Cue2/Sync4/Keylock5 on raw0/1; positive Note38 toggles native A/C or B/D. Manual apply/reconnect starts A/B; optional hardware bank lamps are not driven, so they are not a native state indicator. C/D require app opt-in. Physical mixer targets stay fixed as player banks change. Own raw3 PFL Notes13..16 toggle four fixed targets. Raw3 masterCC27 and cueMix26 are normal; crossCC25 is explicitly inverted. The mapper volumePot constant mistakenly overlaps filterCC17..20; its separate XML and earlier owner chart independently confirm levelCC21..24, which native retains. Duplicate low-pot construction and source shutdown/FX setup are not copied. CUP3 is not held Cue; Load/eject/Shift, pad modes, relative browse/jog formats and calibration, tempo, orientation, booth/monitor and complete feedback/lifecycle/audio remain inactive or open. The earlier mixer-only scope is expanded only by these independently qualified native facts. Every active wire is present in the pinned XML; no script/component code executes or ships.'}}


def g4v_mixer_profiles():
    """Keep the reported fixed mixer addresses outside unqualified player modes."""
    ref=G4V_MIXER_REFERENCES['Gemini G4V']
    p=profile('Gemini G4V',ref['url'])
    p.update(autoSelect=False,definition='reviewed:g4v-primary-native-manual-banks',
        aliases=['Gemini G4V','G4V','G4V Audio'],excludedAliases=['Gemini G2V','G2V','G2V Audio','Gemini Slate 4','Slate 4'],
        hardwareMode='Manual G4V native layout on an exposed MIDI source. Apply/reconnect starts A/B; Deck Select toggles A/C and B/D. Native does not drive the bank lamps. Physical mixer CH1..4 stay A..D on raw3. C/D require app opt-in. Configure app audio separately.',
        scope='Manual39-input native banked Play/held Cue/Sync/Keylock, fixed four-strip gain/EQ/filter/level/PFL and master/cue mix/inverted crossfader. Primary owner and unmerged PR protocol facts only. No automatic identity, outputs or audio route.',
        bankChanges=[{'channel':i,'number':38,'onValue':127,'decks':list('ac' if i==0 else 'bd'),'deckBank':i} for i in range(2)],
        gaps=[ref['review']])
    for index,deck in enumerate('abcd'):
        for action,base in [('gain',1),('high',9),('mid',5),('low',13),('filterKnob',17),('level',21)]:add(p,action,3,base+index,'control',deck=deck)
    for i,deck in enumerate('ab'):
        for action,n in [('play',1),('cuePreview',2),('sync',4),('keylock',5)]:
            add(p,action,i,n,deck=deck);p['inputs'][-1]['deckBank']=i
    for i,deck in enumerate('abcd'):add(p,'cue',3,13+i,deck=deck)
    for action,n in [('master',27),('cueMix',26),('crossfader',25)]:
        add(p,action,3,n,'control')
        if action=='crossfader':p['inputs'][-1]['inverted']=True
    return [p]
